/* Established UI artwork, isolated from the interaction code. See ASSETS.md. */
(() => {
  const variables = {
  "--alchemy-current-gameplay": "data:image/jpeg;base64,",
  "--alchemy-report-icon-atlas": "data:image/jpeg;base64,",
  "--alchemy-capybara-style-atlas": "data:image/jpeg;base64,",
  "--alchemy-material-tile-atlas": "data:image/jpeg;base64,",
  "--alchemy-material-icon-atlas": "data:image/jpeg;base64,",
  "--alchemy-style-atlas": "data:image/jpeg;base64,"
};
  const images = {};
  const root = document.getElementById("ai-alchemy-prototype");
  for (const [name, data] of Object.entries(variables)) root.style.setProperty(name, `url("${data}")`);
  root.querySelectorAll("[data-alchemy-art]").forEach(image => {
    const data = images[image.dataset.alchemyArt];
    if (data) image.src = data;
  });
})();
